 x.tenantId=info.id;const former=['Darvi Group LLP','Darvi Group Agri Tech (Nursery)','Darvi Group Agri Tech','Darvi Group Agro Tech','Darvi Agri Developer LLP — Vikshha'];x.business={...x.business,...info,name:(former.includes(x.business?.name)||!x.business?.name)?info.name:x.business.name,invoicePrefix:x.business?.invoicePrefix||info.invoicePrefix};
