 if(t.dataset.draft&&ui.draft){if(t.dataset.draft==='customerId'){ui.draft.customerId=t.value;for(const key of ['shippingName','shippingPhone','shippingAddress','shippingCity','shippingState','shippingPincode'])ui.draft[key]='';render();return;}if(!isAdmin()&&t.dataset.draft==='transportTaxRate')return; if(!isAdmin()&&t.dataset.draft==='salespersonId'){ui.draft.salespersonId=currentUserId;return;}ui.draft[t.dataset.draft]=t.value;updateDraftTotals();return;}
