function exportLeadsCSV(){if(!can('leads'))return;const hdr=['Lead ID','Business','Name','Phone','Email','Interest','Source','Stage','Assigned staff','Next follow-up','Created'];const rows=visibleLeads().map(l=>[l.id,db.business.name,l.name,l.phone,l.email,l.interest,l.source,l.stage,store.staff.find(s=>s.id===l.assignedTo)?.name||'',l.followUpAt,l.createdAt]);const csv=[hdr,...rows].map(row=>row.map(c=>'"'+String(c??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');downloadFile('\ufeff'+csv,`darvi-leads-${store.activeBusinessId}-${localDate()}.csv`,'text/csv;charset=utf-8');}


// --- Seznik 2POS Bluetooth Thermal Print Service ---
async function printViaThermalAction(id, docType = 'invoice') {
  if (!window.DarviPrinter) {
    toast('Printer engine not loaded.', 'error');
    return;
  }
  const doc = (docType === 'quotation')
    ? db.estimates.find(x => x.id === id)
    : db.invoices.find(x => x.id === id);
  if (!doc) { toast('Document not found.', 'error'); return; }
  if (!doc.lines || !doc.lines.length) { toast('Invoice has no items.', 'error'); return; }

  // Prevent duplicate submissions while request is in flight
  const printBtns = document.querySelectorAll('[data-action="print-thermal"][data-id="' + id + '"], [data-action="print-cleanter"][data-id="' + id + '"]');
  printBtns.forEach(b => { b.disabled = true; b.textContent = '⏳ Printing…'; });

  toast('Sending to Seznik 2POS…', 'info');
  try {
    const result = await DarviPrinter.printInvoice(doc, docType);
    if (result.ok) {
      const sentInfo = result.bytesWritten ? ` (${result.bytesWritten} bytes, ${result.durationMs} ms)` : '';
      toast(`Android formatted and sent${sentInfo} to ${result.deviceName || 'the connected printer'} via Bluetooth SPP; physical printing is not acknowledged.`, 'success');
      closeModal();
    } else {
      throw new Error(result.message || 'Print failed');
    }
  } catch (err) {
    console.error('Thermal print error:', err);
    toast('Print error: ' + (err.message || err), 'error');
    showThermalPrintErrorModal(doc, docType, err.message || err);
  } finally {
    printBtns.forEach(b => {
      b.disabled = false;
      b.textContent = (docType === 'quotation') ? '🖨️ Print Quotation (Seznik 2POS)' : '🖨️ Print Bill (Seznik 2POS)';
    });
  }
}

// Cleanter HTTP bridge printer handler
async function printViaCleanterBridgeAction(id, docType = 'invoice') {
  const doc = (docType === 'quotation') ? db.estimates.find(x => x.id === id) : db.invoices.find(x => x.id === id);
  if (!doc) return toast('Document not found.', 'error');
  if (!window.CleanterPrinter) return toast('Cleanter module not loaded.', 'error');

  toast('Sending receipt to Cleanter bridge (localhost:9100)…', 'info');
  try {
    const res = await CleanterPrinter.printInvoice(doc, docType);
    if (res.ok) {
      toast('Receipt printed successfully via Cleanter!', 'success');
      closeModal();
    } else {
      toast('Cleanter print failed: ' + (res.message || 'Unknown error'), 'error');
      if (res.isHttpPnaBlock) {
        showModal('Cleanter Localhost Access', `
          <div class="notice warning">
            <strong>Android Chrome Localhost Security Notice</strong><br/><br/>
            Android Chrome blocks web pages loaded over local HTTP from accessing <code>http://localhost:9100</code>.<br/><br/>
            <strong>Recommended Solutions:</strong><br/>
            1. <strong>Direct Bluetooth (Fastest):</strong> Run the <strong>Darvi Billing Android APK</strong> for instant 1-second printing directly via Bluetooth Classic.<br/>
            2. <strong>Switch to Secure Mode:</strong> Open via HTTPS at <a href="${res.httpsUrl}" class="button button-small button-primary" style="margin-top:6px;display:inline-block">HTTPS Port 8443</a><br/>
            3. <strong>Chrome Flag:</strong> Open <code>chrome://flags/#block-insecure-private-network-requests</code> in Chrome and set to <strong>Disabled</strong>.
          </div>
        `);
      }
    }
  } catch (e) {
    toast('Cleanter error: ' + (e.message || e), 'error');
  }
}

// Backward compatibility alias
async function printViaCleanterAction(id, docType) {
  return printViaThermalAction(id, docType);
}

