// --- Live Bluetooth Header Pill ---
function updateBtButtonState(status) {
  const btn = qs('#bt-printer-btn');
  if (!btn) return;
  const s = status || (window.DarviPrinter ? DarviPrinter.getStatus() : { state: 'Disconnected' });

  if (s.isConnected) {
    btn.className = 'button button-small bt-top-btn connected';
    btn.innerHTML = `🟢 ${esc(s.deviceName || 'SSEZNIK2POS')} <span class="status-dot online"></span>`;
  } else if (s.state === 'Connecting' || s.state === 'Searching') {
    btn.className = 'button button-small bt-top-btn';
    btn.innerHTML = `🟡 Connecting… <span class="status-dot connecting"></span>`;
  } else if (s.state === 'BluetoothDisabled' || s.state === 'PermissionRequired') {
    btn.className = 'button button-small bt-top-btn';
    btn.innerHTML = `⚠️ Bluetooth Off`;
  } else {
    btn.className = 'button button-small bt-top-btn';
    btn.innerHTML = `🖨️ Seznik 2POS`;
  }
}
if (typeof window !== 'undefined' && window.DarviPrinter) {
  DarviPrinter.onStatusChange(updateBtButtonState);
}

